#!/usr/bin/env python3
from __future__ import annotations

import argparse
import io
import re
import subprocess
import sys
import tokenize
from dataclasses import dataclass
from pathlib import Path

BARE_ANY_RE = re.compile(r"(?P<prefix>(?:->|:)\s*)(?P<qualifier>(?:typing|t)\.)?Any\b")
ALLOW_ANY_WITH_REASON_RE = re.compile(r"#\s*allow-any:\s*\S")
ALLOW_ANY_COMMENT_RE = re.compile(r"#\s*allow-any\b")
HUNK_RE = re.compile(
    r"^@@ -(?P<old_start>\d+)(?:,(?P<old_count>\d+))? "
    r"\+(?P<new_start>\d+)(?:,(?P<new_count>\d+))? @@"
)


@dataclass(frozen=True)
class Issue:
    path: str
    line_number: int
    line: str
    message: str


@dataclass(frozen=True)
class AnalysisResult:
    issues: list[Issue]

    @property
    def has_errors(self) -> bool:
        return bool(self.issues)


@dataclass
class _FileState:
    path: str | None = None
    new_line_number: int = 0
    removed_bare_any_count: int = 0
    added_issues: list[Issue] | None = None

    def __post_init__(self) -> None:
        if self.added_issues is None:
            self.added_issues = []


def _strip_strings_and_comments(line: str) -> str:
    chars = list(line)
    try:
        tokens = tokenize.generate_tokens(io.StringIO(line).readline)
        for token in tokens:
            if token.type not in {tokenize.STRING, tokenize.COMMENT}:
                continue
            start_col = token.start[1]
            end_col = token.end[1]
            for index in range(start_col, min(end_col, len(chars))):
                chars[index] = " "
    except tokenize.TokenError:
        comment_start = line.find("#")
        if comment_start >= 0:
            for index in range(comment_start, len(chars)):
                chars[index] = " "
    return "".join(chars)


def _is_variadic_any(stripped_line: str, match: re.Match[str]) -> bool:
    before_annotation = stripped_line[: match.start()].rstrip()
    return bool(re.search(r"\*\*?\w+$", before_annotation))


def _bare_any_count(line: str) -> int:
    stripped_line = _strip_strings_and_comments(line)
    return sum(
        1
        for match in BARE_ANY_RE.finditer(stripped_line)
        if not _is_variadic_any(stripped_line, match)
    )


def _issues_for_added_line(path: str, line_number: int, line: str) -> list[Issue]:
    stripped_line = _strip_strings_and_comments(line)
    if ALLOW_ANY_WITH_REASON_RE.search(line):
        return []

    issues: list[Issue] = []
    for match in BARE_ANY_RE.finditer(stripped_line):
        if _is_variadic_any(stripped_line, match):
            continue

        if ALLOW_ANY_COMMENT_RE.search(line):
            message = "allow-any escape hatch must include a reason"
        else:
            message = (
                "New bare Any annotation. Use a concrete type, object, a "
                "Protocol, or add '# allow-any: reason' for a framework boundary."
            )
        issues.append(
            Issue(
                path=path,
                line_number=line_number,
                line=line.strip(),
                message=message,
            )
        )
    return issues


def _path_from_diff_header(line: str) -> str | None:
    if line == "+++ /dev/null":
        return None
    if line.startswith("+++ b/"):
        return line.removeprefix("+++ b/")
    if line.startswith("+++ "):
        return line.removeprefix("+++ ")
    return None


def _finalize_file(state: _FileState, issues: list[Issue]) -> None:
    added_issues = state.added_issues or []
    if state.removed_bare_any_count >= len(added_issues):
        return
    issues.extend(added_issues[state.removed_bare_any_count :])


def analyze_diff(diff_text: str) -> AnalysisResult:
    issues: list[Issue] = []
    state = _FileState()

    for raw_line in diff_text.splitlines():
        if raw_line.startswith("diff --git "):
            _finalize_file(state, issues)
            state = _FileState()
            continue

        if raw_line.startswith("+++ "):
            state.path = _path_from_diff_header(raw_line)
            continue

        hunk_match = HUNK_RE.match(raw_line)
        if hunk_match is not None:
            state.new_line_number = int(hunk_match.group("new_start"))
            continue

        if state.path is None:
            continue

        if raw_line.startswith("+") and not raw_line.startswith("+++"):
            line = raw_line[1:]
            assert state.added_issues is not None
            state.added_issues.extend(
                _issues_for_added_line(state.path, state.new_line_number, line)
            )
            state.new_line_number += 1
            continue

        if raw_line.startswith("-") and not raw_line.startswith("---"):
            state.removed_bare_any_count += _bare_any_count(raw_line[1:])
            continue

        if raw_line.startswith(" "):
            state.new_line_number += 1

    _finalize_file(state, issues)
    return AnalysisResult(issues=issues)


def _git_diff(args: argparse.Namespace) -> str:
    command = ["git", "diff", "--unified=0", "--no-ext-diff"]
    # --cached only applies to the staged-changes mode; combining it with a
    # revision range is a git usage error (exit 129).
    if args.staged and not args.rev:
        command.append("--cached")
    if args.rev:
        command.append(args.rev)
    command.extend(["--", "*.py"])
    completed = subprocess.run(
        command,
        check=True,
        capture_output=True,
        text=True,
    )
    return completed.stdout


def _read_diff_file(path: Path) -> str:
    if str(path) == "-":
        return sys.stdin.read()
    return path.read_text(encoding="utf-8")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Block newly introduced bare Any annotations in Python diffs."
    )
    source = parser.add_mutually_exclusive_group()
    source.add_argument(
        "--rev",
        help="Git revision or range to diff, for example origin/main...HEAD.",
    )
    source.add_argument(
        "--diff-file",
        type=Path,
        help="Read a unified diff from a file, or '-' for stdin.",
    )
    parser.add_argument(
        "--staged",
        action=argparse.BooleanOptionalAction,
        default=True,
        help="Check staged changes when --rev and --diff-file are omitted.",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    diff_text = _read_diff_file(args.diff_file) if args.diff_file else _git_diff(args)
    result = analyze_diff(diff_text)
    if not result.has_errors:
        return 0

    print("New bare Any annotations were introduced:")
    for issue in result.issues:
        print(f"{issue.path}:{issue.line_number}: {issue.message}")
        print(f"  {issue.line}")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

